SOURCES = {'gdsl1/__init__.py': '\n', 'gdsl1/data.py': '"""Student inputs built from the GDS-ParT JetClass cache.\n\nThe teacher sees the full jet (<=128 particles, 17 features, 4 pairwise\nfeatures). The L1 student sees only the N highest-pT candidates with the\nfeatures a Phase-2 L1 PUPPI candidate carries (pT, eta/phi relative to the\njet axis, charge, particle ID) and the same 4 ParT pairwise features built\nfrom those N candidates.\n"""\nimport numpy as np\nimport torch\n\nfrom .models import MASK_NEG, STUDENT_FEATURES\n\nPAIR_CLIP = 15.0\n\n\ndef pairwise_features(vectors, mask, eps=1e-8):\n    """ParT\'s ln(dR), ln(kT), ln(z), ln(m^2) for every pair; 0 for self\n    pairs and padding. (B,N,4),(B,N) -> (B,N,N,4)."""\n    v = vectors.float()\n    px, py, pz, e = v.unbind(-1)\n    pt = torch.sqrt(px ** 2 + py ** 2).clamp(min=eps)\n    rap = 0.5 * torch.log((e + pz).clamp(min=eps) / (e - pz).clamp(min=eps))\n    phi = torch.atan2(py, px)\n    drap = rap[:, :, None] - rap[:, None, :]\n    dphi = torch.remainder(phi[:, :, None] - phi[:, None, :] + torch.pi, 2 * torch.pi) - torch.pi\n    delta = torch.sqrt(drap ** 2 + dphi ** 2).clamp(min=eps)\n    pt_min = torch.minimum(pt[:, :, None], pt[:, None, :])\n    kt = (pt_min * delta).clamp(min=eps)\n    z = (pt_min / (pt[:, :, None] + pt[:, None, :])).clamp(min=eps)\n    s = v[:, :, None, :] + v[:, None, :, :]\n    m2 = (s[..., 3] ** 2 - s[..., 0] ** 2 - s[..., 1] ** 2 - s[..., 2] ** 2).clamp(min=eps)\n    out = torch.stack([torch.log(delta), torch.log(kt), torch.log(z), torch.log(m2)], dim=-1)\n    n = mask.shape[1]\n    valid = mask[:, :, None] & mask[:, None, :] & ~torch.eye(n, dtype=torch.bool, device=mask.device)\n    return out * valid[..., None]\n\n\ndef top_n(feats, vectors, mask, n):\n    """Keep the n highest-pT particles (feature 0 is log pT), zero-padded to n."""\n    B, M = mask.shape\n    key = torch.where(mask, feats[..., 0].float(), torch.full_like(feats[..., 0].float(), -1e9))\n    idx = key.argsort(dim=1, descending=True)[:, :n]\n    g = lambda t: torch.gather(t, 1, idx[..., None].expand(-1, -1, t.shape[-1]))\n    f, v, m = g(feats), g(vectors), torch.gather(mask, 1, idx)\n    if M < n:\n        pad = n - M\n        f = torch.nn.functional.pad(f, (0, 0, 0, pad))\n        v = torch.nn.functional.pad(v, (0, 0, 0, pad))\n        m = torch.nn.functional.pad(m, (0, pad), value=False)\n    return f * m[..., None], v * m[..., None], m\n\n\ndef student_inputs(x, v, mask):\n    """x: (B,N,10) student features, v: (B,N,4) 4-vectors, mask (B,N) ->\n    dict with x, u, w, m as consumed by gdsl1.models."""\n    mask = mask.bool()\n    mf = mask.float()\n    n_real = mf.sum(1, keepdim=True).clamp(min=1.0)\n    u = pairwise_features(v, mask).clamp(-PAIR_CLIP, PAIR_CLIP)\n    m = torch.where(mask[:, None, :], 0.0, MASK_NEG).expand(-1, mask.shape[1], -1)\n    return {"x": x.float() * mf[..., None], "u": u, "w": mf / n_real, "m": m.contiguous()}\n\n\ndef select_student_features(feats17):\n    return feats17[..., STUDENT_FEATURES]\n\n\ndef synthetic_batch(batch_size=32, n=16, n_classes=10, seed=0, device="cpu"):\n    """Random but physically shaped batch for smoke tests (no data needed)."""\n    g = torch.Generator().manual_seed(seed)\n    n_real = torch.randint(3, n + 1, (batch_size,), generator=g)\n    mask = torch.arange(n)[None, :] < n_real[:, None]\n    pt = torch.rand(batch_size, n, generator=g) * 50 + 1\n    eta = torch.randn(batch_size, n, generator=g) * 0.3\n    phi = torch.randn(batch_size, n, generator=g) * 0.3\n    mass = torch.zeros_like(pt)\n    px, py, pz = pt * torch.cos(phi), pt * torch.sin(phi), pt * torch.sinh(eta)\n    e = torch.sqrt(px ** 2 + py ** 2 + pz ** 2 + mass ** 2)\n    v = torch.stack([px, py, pz, e], -1) * mask[..., None]\n    x = torch.randn(batch_size, n, len(STUDENT_FEATURES), generator=g)\n    b = student_inputs(x, v, mask)\n    b["y"] = torch.randint(0, n_classes, (batch_size,), generator=g)\n    b["teacher_logits"] = torch.randn(batch_size, n_classes, generator=g)\n    return {k: t.to(device) for k, t in b.items()}\n\n\ndef numpy_inputs(batch, names):\n    return [np.ascontiguousarray(batch[k].detach().cpu().numpy().astype(np.float32)) for k in names]\n', 'gdsl1/hls.py': '\ufeff"""hls4ml conversion, bit-accurate emulation and latency/resource estimates.\n\nWorks around five issues in hls4ml 1.3\'s PyTorch frontend found while\nbuilding this project (each one is validated in tests/test_hls.py):\n\n1. ``nn.Linear`` on rank>=3 inputs is lowered to a pointwise conv whose\n   weights are read as (n_in, n_out), but the parser passes torch\'s\n   (n_out, n_in). We transpose in the parser when channels_last_conversion\n   is off. Without this the C-simulation disagrees with PyTorch.\n2. ``nn.Softmax(dim=-1)`` on a (N, N) tensor is emitted as one softmax over\n   all N*N values. We set n_outer/n_inner so ``softmax_multidim`` normalizes\n   each row.\n3. On Windows there is no g++/bash; we compile the C-sim library with the\n   zig C++ toolchain (``pip install ziglang``). The ap_types headers\n   forward-declare ``std::complex`` in a way libc++ rejects, so we include\n   <complex> instead.\n4. ModelGraph._compile calls dlclose, which only exists on Linux/macOS.\n5. The einsum parser reports input0\'s shape as the layer\'s output shape,\n   which breaks every downstream layer when they differ.\n"""\nimport ctypes\nimport importlib\nimport math\nimport os\nimport platform\nimport subprocess\nimport sys\nimport uuid\n\nimport numpy as np\n\n_PATCHED = False\n\n\ndef apply_patches():\n    global _PATCHED\n    if _PATCHED:\n        return\n    import hls4ml  # noqa: F401\n    P = importlib.import_module("hls4ml.converters.pytorch_to_hls")\n\n    lin = P.layer_handlers["Linear"]\n\n    def linear(operation, layer_name, input_names, input_shapes, node, class_object, reader, config):\n        layer, shape = lin(operation, layer_name, input_names, input_shapes, node, class_object,\n                           reader, config)\n        if config.get("ChannelsLastConversion", "off") == "off":\n            layer["weight_data"] = np.ascontiguousarray(layer["weight_data"].T)\n        return layer, shape\n\n    act = P.layer_handlers["Softmax"]\n\n    def activation(operation, layer_name, input_names, input_shapes, node, class_object, reader,\n                   config):\n        layer, shape = act(operation, layer_name, input_names, input_shapes, node, class_object,\n                           reader, config)\n        if layer["class_name"] == "Softmax":\n            dims = [d for d in input_shapes[0][1:]]\n            ax = layer.get("axis", -1)\n            ax = ax if ax >= 0 else len(dims) + ax + 1\n            layer["n_outer"] = int(np.prod(dims[:ax - 1])) if ax > 1 else 1\n            layer["n_inner"] = int(np.prod(dims[ax:])) if ax < len(dims) else 1\n            layer["axis"] = -1 if layer["n_inner"] == 1 else ax\n        return layer, shape\n\n    P.layer_handlers["Linear"] = linear\n\n    ein = P.layer_handlers["einsum"]\n\n    def einsum(operation, layer_name, input_names, input_shapes, node, class_object, reader, config):\n        layer, _ = ein(operation, layer_name, input_names, input_shapes, node, class_object,\n                       reader, config)\n        # upstream returns input0\'s shape and keeps a dummy batch dim in the\n        # HLS output variable; report the true per-sample output shape for both\n        layer["out_shape"] = tuple(layer["out_shape"][1:])\n        return layer, [None] + list(layer["out_shape"])\n\n    P.layer_handlers["einsum"] = einsum\n    for name in ("Softmax", "ReLU", "Sigmoid", "Tanh", "LeakyReLU", "ELU", "PReLU", "Threshold"):\n        if P.layer_handlers.get(name) is act:\n            P.layer_handlers[name] = activation\n\n    if platform.system() == "Windows":\n        from hls4ml.backends.fpga.fpga_backend import FPGABackend\n        from hls4ml.model.graph import ModelGraph\n        FPGABackend.compile = _compile_with_zig\n\n        def _compile(self):\n            self.config.config["Stamp"] = uuid.uuid4().hex[:8]\n            self.write()\n            self._top_function_lib = ctypes.cdll.LoadLibrary(self.config.backend.compile(self))\n\n        ModelGraph._compile = _compile\n    _PATCHED = True\n\n\ndef _compile_with_zig(self, model):\n    d = os.path.abspath(model.config.get_output_dir())\n    name = model.config.get_project_name()\n    for f in ("ap_int_special.h", "ap_fixed_special.h"):\n        p = os.path.join(d, "firmware", "ap_types", f)\n        if os.path.exists(p):\n            s = open(p).read()\n            s = s.replace("template<typename _Tp> class complex;", "")\n            s = s.replace("// #include <complex>", "#include <complex>")\n            open(p, "w").write(s)\n    out = os.path.join(d, "firmware", f"{name}-{model.config.get_config_value(\'Stamp\')}.dll")\n    wdir = d.replace("\\\\", "/") + "/firmware/weights"\n    cmd = [sys.executable, "-m", "ziglang", "c++", "-O1", "-std=c++17", "-shared",\n           "-Ifirmware/ap_types/", f\'-DWEIGHTS_DIR="{wdir}"\',\n           f"firmware/{name}.cpp", f"{name}_bridge.cpp", "-o", out]\n    r = subprocess.run(cmd, cwd=d, capture_output=True, text=True)\n    if r.returncode:\n        print(r.stderr[-4000:])\n        raise RuntimeError(f"C-sim compile failed for {d}")\n    return out\n\n\n# ---------------------------------------------------------------------------\n# Conversion\n# ---------------------------------------------------------------------------\ndef input_shapes(model, n_particles, n_feat=10, n_pair=4):\n    s = {"x": (n_particles, n_feat), "u": (n_particles, n_particles, n_pair),\n         "w": (n_particles,), "m": (n_particles, n_particles)}\n    return [s[k] for k in model.inputs]\n\n\ndef _positions_per_layer(model, shapes):\n    """hls4ml layer name -> number of particle/pair positions of each nn.Linear\n    applied to a rank>=2 tensor (used as its ParallelizationFactor)."""\n    import torch\n    out, hooks = {}, []\n    for name, mod in model.named_modules():\n        if isinstance(mod, torch.nn.Linear):\n            def hook(m, i, o, name=name):\n                if o.dim() > 2:\n                    out[name.replace(".", "_")] = int(np.prod(o.shape[1:-1]))\n            hooks.append(mod.register_forward_hook(hook))\n    with torch.no_grad():\n        model(*[torch.zeros(1, *s) for s in shapes])\n    for h in hooks:\n        h.remove()\n    return out\n\n\ndef hls_config(model, shapes, quant, reuse_factor=1, strategy="Latency", table_bits=10,\n               accum=None, parallel=None):\n    """Per-layer config mirroring the QAT precision plan.\n    quant: dict {"weight": [W,I], "bias": [W,I], "act": [W,I]}."""\n    import hls4ml\n    W = lambda k: "ap_fixed<{},{},AP_RND_CONV,AP_SAT>".format(*quant[k])\n    act = W("act")\n    positions = _positions_per_layer(model, shapes)\n    acc = accum or "ap_fixed<{},{},AP_RND_CONV,AP_SAT>".format(quant["act"][0] + 8, quant["act"][1] + 6)\n    cfg = hls4ml.utils.config_from_pytorch_model(\n        model, input_shape=shapes, granularity="name", backend="Vitis",\n        default_precision=act, default_reuse_factor=reuse_factor,\n        channels_last_conversion="off", transpose_outputs=False)\n    cfg["Model"]["Strategy"] = strategy\n    for name, lc in cfg["LayerName"].items():\n        lc["ReuseFactor"] = reuse_factor\n        # Dense on (N, D) / (N, N, P) tensors becomes a pointwise conv whose default\n        # ParallelizationFactor=1 processes one particle (pair) per clock. At L1 all\n        # positions run in parallel; hls4ml clamps this to the largest valid value.\n        if name in positions:\n            lc["ParallelizationFactor"] = parallel or positions[name]\n        prec = lc.get("Precision")\n        if not isinstance(prec, dict):\n            continue\n        for k in list(prec):\n            if k == "weight":\n                prec[k] = W("weight")\n            elif k == "bias":\n                prec[k] = W("bias")\n            elif k == "accum":\n                prec[k] = acc\n            elif k in ("result",):\n                prec[k] = act\n            elif k in ("exp_table", "inv_table", "inv_inp", "table"):\n                prec[k] = "ap_fixed<18,8,AP_RND_CONV,AP_SAT>"\n        if "TableSize" in lc:\n            lc["TableSize"] = 2 ** table_bits\n    return cfg\n\n\ndef convert(model, out_dir, n_particles, quant, reuse_factor=1, strategy="Latency",\n            part="xcvu13p-flga2577-2-e", clock_period=4.17, compile=True, verbose=False,\n            parallel=None):\n    """model: float or QAT-baked student (eval mode). Returns hls4ml ModelGraph."""\n    apply_patches()\n    import hls4ml\n    model = model.cpu().eval()\n    shapes = input_shapes(model, n_particles, model.cfg["n_feat"], model.cfg["n_pair"])\n    cfg = hls_config(model, shapes, quant, reuse_factor, strategy, parallel=parallel)\n    hm = hls4ml.converters.convert_from_pytorch_model(\n        model, input_shape=shapes, hls_config=cfg, output_dir=out_dir, backend="Vitis",\n        io_type="io_parallel", part=part, clock_period=clock_period,\n        channels_last_conversion="off", transpose_outputs=False, verbose=verbose)\n    if compile:\n        hm.compile()\n    else:\n        hm.write()\n    return hm\n\n\ndef predict(hm, batch, names):\n    xs = [np.ascontiguousarray(batch[k].detach().cpu().numpy().astype(np.float32)) for k in names]\n    y = np.asarray(hm.predict(xs if len(xs) > 1 else xs[0]))\n    return y.reshape(xs[0].shape[0], -1)\n\n\n# ---------------------------------------------------------------------------\n# Analytic latency / resource estimate (replace with Vitis csynth reports)\n# ---------------------------------------------------------------------------\ndef _shape(layer):\n    return [int(s) for s in layer.get_output_variable().shape]\n\n\ndef estimate(hm, reuse_factor=1, clock_ns=4.17, dsp_min_bits=10):\n    """Analytic per-layer multiplier count and critical-path pipeline depth\n    for io_parallel / Latency strategy. NOT a synthesis result.\n\n    Model (see docs/ESTIMATES.md):\n      Dense / pointwise conv:  mults = positions*nonzero(W) / n_partitions,\n                               depth = (2 + ceil(log2 n_in)) * RF + (n_partitions - 1)\n      Einsum:                  mults = prod(out)*contract, depth = 2 + ceil(log2 contract)\n      Merge(mul):              mults = prod(out), depth 1;  Merge(add): depth 1\n      Activation (ReLU):       depth 1;  Sigmoid/Tanh (LUT): depth 2\n      Softmax (stable, LUT):   depth = 6 + 2*ceil(log2 n), mults = prod(out)\n    Latency = longest path through the layer DAG (parallel branches overlap).\n    Multipliers with both operands >= dsp_min_bits wide map to DSP48s, the\n    rest to LUT fabric (~W_a*W_b/2 LUTs each, Vivado\'s usual mapping).\n    """\n    rows, dsp, lut_mult, finish = [], 0, 0, {}\n    for layer in hm.get_layers():\n        cls = layer.class_name\n        out = _shape(layer)\n        npos = int(np.prod(out[:-1])) if len(out) > 1 else 1\n        mults, depth, wp, ip = 0, 1, 0, 0\n        if cls in ("Dense", "PointwiseConv1D", "PointwiseConv2D", "Conv1D", "Conv2D"):\n            w = layer.get_weights("weight").data\n            n_in = int(layer.get_attr("n_in") or layer.get_attr("n_chan"))\n            n_part = int(layer.get_attr("n_partitions") or 1) if "Conv" in cls else 1\n            mults = npos * int(np.count_nonzero(w)) // n_part\n            depth = (2 + math.ceil(math.log2(max(n_in, 2)))) * reuse_factor + (n_part - 1)\n            wp = layer.get_attr("weight_t").precision.width\n            ip = layer.get_input_variable().type.precision.width\n        elif cls == "Einsum":\n            eq = layer.get_attr("equation")\n            ins, o = eq.split("->")\n            a, b = ins.split(",")\n            sizes = {}\n            for sub, shp in ((a, layer.get_attr("inp0_shape")), (b, layer.get_attr("inp1_shape"))):\n                for ch, n in zip(sub, shp):\n                    sizes[ch] = int(n)\n            contract = int(np.prod([sizes[ch] for ch in set(a) & set(b) if ch not in o])) or 1\n            mults = int(np.prod(out)) * contract\n            depth = 2 + math.ceil(math.log2(max(contract, 2)))\n            wp = ip = layer.get_input_variable().type.precision.width\n        elif cls == "Merge":\n            if layer.get_attr("op") in ("multiply", "mul"):\n                mults = int(np.prod(out))\n            wp = ip = layer.get_input_variable().type.precision.width\n        elif cls == "Softmax":\n            depth = 6 + 2 * math.ceil(math.log2(max(out[-1], 2)))\n            mults = int(np.prod(out))\n            wp = ip = 18\n        elif cls == "Activation":\n            depth = 2 if layer.get_attr("activation") in ("sigmoid", "tanh") else 1\n        elif cls in ("Input", "Reshape", "Transpose"):\n            depth = 0\n        if mults:\n            if min(wp, ip) >= dsp_min_bits:\n                dsp += math.ceil(mults / reuse_factor)\n            else:\n                lut_mult += math.ceil(mults / reuse_factor) * (wp * ip) // 2\n        start = max([finish.get(i, 0) for i in layer.inputs] or [0])\n        finish[layer.name] = start + depth\n        for o in layer.outputs:\n            finish[o] = finish[layer.name]\n        rows.append({"layer": layer.name, "class": cls, "out": out, "mults": mults,\n                     "cycles": depth, "done_at": finish[layer.name]})\n    cycles = max(finish.values())\n    return {"cycles": cycles, "latency_ns": cycles * clock_ns, "ii": reuse_factor,\n            "dsp": dsp, "lut_mult": lut_mult, "layers": rows, "clock_ns": clock_ns}\n\n\ndef parse_vitis_report(prj_dir, project="myproject"):\n    """Read latency/resources from a real csynth report if one exists."""\n    import xml.etree.ElementTree as ET\n    hits = []\n    for root, _, files in os.walk(prj_dir):\n        for f in files:\n            if f == f"{project}_csynth.xml" or f == "csynth.xml":\n                hits.append(os.path.join(root, f))\n    if not hits:\n        return None\n    r = ET.parse(hits[0]).getroot()\n    g = lambda p: r.findtext(p)\n    return {\n        "latency_cycles_best": g(".//PerformanceEstimates/SummaryOfOverallLatency/Best-caseLatency"),\n        "latency_cycles_worst": g(".//PerformanceEstimates/SummaryOfOverallLatency/Worst-caseLatency"),\n        "ii": g(".//PerformanceEstimates/SummaryOfOverallLatency/Interval-min"),\n        "clock_ns": g(".//PerformanceEstimates/SummaryOfTimingAnalysis/EstimatedClockPeriod"),\n        **{k: g(f".//AreaEstimates/Resources/{k}") for k in ("BRAM_18K", "DSP", "FF", "LUT", "URAM")},\n        **{f"avail_{k}": g(f".//AreaEstimates/AvailableResources/{k}") for k in ("BRAM_18K", "DSP", "FF", "LUT")},\n    }\n', 'gdsl1/models.py': '"""L1-trigger-sized students: GDS-ParT-L1, DeepSets and MLP baselines.\n\nInputs are drawn from one batch dict; each model lists the ones it uses in\n``model.inputs`` (call as ``model(*[batch[k] for k in model.inputs])``):\n\n    x : (B, N, F)     per-particle features (L1 PUPPI-candidate-like)\n    u : (B, N, N, P)  pairwise features (from the pairwise front-end)\n    w : (B, N)        pooling weights = mask / n_real  (0 for padded slots)\n    m : (B, N, N)     additive key mask for softmax: 0 real, MASK_NEG padded\n\nEvery op is one hls4ml\'s PyTorch frontend can parse (nn.Linear, ReLU,\nSigmoid, Softmax(dim=-1), einsum, mul, add, squeeze): no LayerNorm,\nno GELU, no reshapes of the head dimension (heads are separate Linear layers).\n"""\nimport torch\nimport torch.nn as nn\n\nfrom .quant import fake_quant\n\nMASK_NEG = -16.0  # additive key-mask value; exp(-16) ~ 1e-7, inside ap_fixed<16,6>\n\nSTUDENT_FEATURES = [0, 2, 5, 6, 7, 8, 9, 10, 11, 12]\nFEATURE_NAMES = ["log_pt", "log_ptrel", "deta", "dphi", "charge",\n                 "is_ch_had", "is_neu_had", "is_photon", "is_electron", "is_muon"]\n\n\nclass _QATMixin(nn.Module):\n    qat = False\n    act_fp = None\n\n    def aq(self, t):\n        """Activation fake-quant during QAT; disappears when qat is False\n        (so torch.fx / hls4ml never see it)."""\n        return fake_quant(t, self.act_fp) if self.qat else t\n\n\nclass GDSParTL1(_QATMixin):\n    """Tiny gated dual-stream transformer.\n\n    Pairwise stream:  rel_ij = ReLU(W_p u_ij)                 (B,N,N,Dp)\n    Relational gate:  s_i = sum_j w_j rel_ij  (masked mean)    (B,N,Dp)\n                      gq_i = sigmoid(G_q s_i), gk_i = sigmoid(G_k s_i)\n    Attention/head:   q = (W_q h) * gq, k = (W_k h) * gk\n                      A = softmax(q k^T + b(rel))   or   ReLU(q) ReLU(k)^T  ("linear")\n    Pool:             z = sum_i w_i h_i  ->  MLP head\n    This keeps GDS-ParT\'s two ideas (multiplicative Q/K gating from relations,\n    ParT-style pair bias) in an O(N^2 * Dp) form small enough for N=16.\n    """\n\n    def __init__(self, n_feat=10, n_pair=4, n_particles=16, n_classes=10, embed_dim=16,\n                 pair_dim=4, n_heads=2, n_blocks=1, ffn_dim=16, attn="softmax",\n                 pair_bias=True, gate=True):\n        super().__init__()\n        assert attn in ("softmax", "linear")\n        assert embed_dim % n_heads == 0\n        self.cfg = dict(n_feat=n_feat, n_pair=n_pair, n_particles=n_particles,\n                        n_classes=n_classes, embed_dim=embed_dim, pair_dim=pair_dim,\n                        n_heads=n_heads, n_blocks=n_blocks, ffn_dim=ffn_dim, attn=attn,\n                        pair_bias=pair_bias, gate=gate)\n        hd = embed_dim // n_heads\n        self.attn, self.n_heads, self.n_blocks = attn, n_heads, n_blocks\n        self.use_gate, self.use_bias = gate, pair_bias and attn == "softmax"\n\n        self.embed = nn.Linear(n_feat, embed_dim)\n        self.embed_act = nn.ReLU()\n        self.pair = nn.Linear(n_pair, pair_dim)\n        self.pair_act = nn.ReLU()\n        L = lambda i, o: nn.ModuleList([nn.Linear(i, o) for _ in range(n_blocks * n_heads)])\n        A = lambda cls: nn.ModuleList([cls() for _ in range(n_blocks * n_heads)])\n        self.q, self.k, self.v = L(embed_dim, hd), L(embed_dim, hd), L(embed_dim, hd)\n        if gate:\n            self.gq, self.gk = L(pair_dim, hd), L(pair_dim, hd)\n            self.gq_act, self.gk_act = A(nn.Sigmoid), A(nn.Sigmoid)\n        if self.use_bias:\n            self.bias = L(pair_dim, 1)\n        if attn == "softmax":\n            self.softmax = nn.ModuleList([nn.Softmax(dim=-1) for _ in range(n_blocks * n_heads)])\n        else:\n            self.q_act, self.k_act = A(nn.ReLU), A(nn.ReLU)\n        # per-head output projections summed == one projection of the concatenated heads (avoids cat)\n        self.out = nn.ModuleList([nn.Linear(hd, embed_dim, bias=(i % n_heads == 0))\n                                  for i in range(n_blocks * n_heads)])\n        self.ff1 = nn.ModuleList([nn.Linear(embed_dim, ffn_dim) for _ in range(n_blocks)])\n        self.ff_act = nn.ModuleList([nn.ReLU() for _ in range(n_blocks)])\n        self.ff2 = nn.ModuleList([nn.Linear(ffn_dim, embed_dim) for _ in range(n_blocks)])\n        self.head1 = nn.Linear(embed_dim, embed_dim)\n        self.head_act = nn.ReLU()\n        self.head2 = nn.Linear(embed_dim, n_classes)\n\n    inputs = ("x", "u", "w", "m")\n\n    def forward(self, x, u, w, m):\n        return self._body(x, u, w, m)\n\n    def _body(self, x, u, w, m):\n        aq = self.aq\n        h = aq(self.embed_act(self.embed(x)))\n        rel = aq(self.pair_act(self.pair(u)))                          # (B,N,N,Dp)\n        s = aq(torch.einsum("bijd,bj->bid", rel, w)) if self.use_gate else None\n        for blk in range(self.n_blocks):\n            heads = []\n            for hh in range(self.n_heads):\n                i = blk * self.n_heads + hh\n                q, k, v = aq(self.q[i](h)), aq(self.k[i](h)), aq(self.v[i](h))\n                if self.use_gate:\n                    q = aq(q * aq(self.gq_act[i](self.gq[i](s))))\n                    k = aq(k * aq(self.gk_act[i](self.gk[i](s))))\n                if self.attn == "softmax":\n                    logits = aq(torch.einsum("bnd,bmd->bnm", q, k))\n                    if self.use_bias:\n                        logits = logits + aq(self.bias[i](rel).squeeze(-1))\n                    logits = logits + m\n                    a = aq(self.softmax[i](logits))\n                else:\n                    # out_n = sum_m w_m relu(q_n).relu(k_m) v_m ; w (=mask/N) drops padding\n                    q, k = aq(self.q_act[i](q)), aq(self.k_act[i](k))\n                    kw = aq(torch.einsum("bmd,bm->bmd", k, w))\n                    kv = aq(torch.einsum("bmd,bme->bde", kw, v))\n                    heads.append(aq(torch.einsum("bnd,bde->bne", q, kv)))\n                    continue\n                heads.append(aq(torch.einsum("bnm,bmd->bnd", a, v)))\n            att = aq(self.out[blk * self.n_heads](heads[0]))\n            for hh in range(1, self.n_heads):\n                att = aq(att + aq(self.out[blk * self.n_heads + hh](heads[hh])))\n            h = aq(h + att)\n            h = aq(h + aq(self.ff2[blk](aq(self.ff_act[blk](self.ff1[blk](h))))))\n        z = aq(torch.einsum("bnd,bn->bd", h, w))\n        return self.head2(aq(self.head_act(self.head1(z))))\n\n\nclass GDSParTL1Linear(GDSParTL1):\n    """Softmax-free variant: ReLU-kernel linear attention (no key mask input).\n    Separate class so torch.fx sees a 3-input signature."""\n\n    inputs = ("x", "u", "w")\n\n    def __init__(self, **kw):\n        kw["attn"] = "linear"\n        super().__init__(**kw)\n\n    def forward(self, x, u, w):\n        return self._body(x, u, w, None)\n\n\nclass DeepSetsL1(_QATMixin):\n    """phi (per particle) -> masked mean -> rho, as in the hls4ml DeepSets/\n    jet-tagging literature (e.g. Odagiu et al. 2024)."""\n\n    def __init__(self, n_feat=10, n_pair=4, n_particles=16, n_classes=10, phi_dim=32,\n                 rho_dim=32):\n        super().__init__()\n        self.cfg = dict(n_feat=n_feat, n_pair=n_pair, n_particles=n_particles,\n                        n_classes=n_classes, phi_dim=phi_dim, rho_dim=rho_dim)\n        self.phi1, self.phi1_act = nn.Linear(n_feat, phi_dim), nn.ReLU()\n        self.phi2, self.phi2_act = nn.Linear(phi_dim, phi_dim), nn.ReLU()\n        self.rho1, self.rho1_act = nn.Linear(phi_dim, rho_dim), nn.ReLU()\n        self.rho2 = nn.Linear(rho_dim, n_classes)\n\n    inputs = ("x", "w")\n\n    def forward(self, x, w):\n        aq = self.aq\n        h = aq(self.phi1_act(self.phi1(x)))\n        h = aq(self.phi2_act(self.phi2(h)))\n        z = aq(torch.einsum("bnd,bn->bd", h, w))\n        return self.rho2(aq(self.rho1_act(self.rho1(z))))\n\n\nclass MLPL1(_QATMixin):\n    """Flattened-constituent MLP (Duarte et al. 2018 style, 64-32-32)."""\n\n    def __init__(self, n_feat=10, n_pair=4, n_particles=16, n_classes=10, hidden=(64, 32, 32)):\n        super().__init__()\n        self.cfg = dict(n_feat=n_feat, n_pair=n_pair, n_particles=n_particles,\n                        n_classes=n_classes, hidden=list(hidden))\n        dims = [n_feat * n_particles, *hidden]\n        self.fc = nn.ModuleList([nn.Linear(a, b) for a, b in zip(dims[:-1], dims[1:])])\n        self.act = nn.ModuleList([nn.ReLU() for _ in hidden])\n        self.flatten = nn.Flatten()\n        self.out = nn.Linear(dims[-1], n_classes)\n\n    inputs = ("x",)\n\n    def forward(self, x):\n        h = self.flatten(x)\n        for fc, act in zip(self.fc, self.act):\n            h = self.aq(act(fc(h)))\n        return self.out(h)\n\n\nVARIANTS = {\n    # name: (class, kwargs)\n    "gds_l1_softmax": (GDSParTL1, dict(embed_dim=16, pair_dim=4, n_heads=2, n_blocks=1,\n                                       ffn_dim=16, attn="softmax")),\n    "gds_l1_linear": (GDSParTL1, dict(embed_dim=16, pair_dim=4, n_heads=2, n_blocks=1,\n                                      ffn_dim=16, attn="linear")),\n    "gds_l1_nogate": (GDSParTL1, dict(embed_dim=16, pair_dim=4, n_heads=2, n_blocks=1,\n                                      ffn_dim=16, attn="softmax", gate=False, pair_bias=True)),\n    "deepsets": (DeepSetsL1, dict(phi_dim=32, rho_dim=32)),\n    "mlp": (MLPL1, dict(hidden=(64, 32, 32))),\n}\n\nMODEL_CLASSES = {c.__name__: c for c in (GDSParTL1, GDSParTL1Linear, DeepSetsL1, MLPL1)}\n\n\ndef build(variant, n_particles=16, n_feat=len(STUDENT_FEATURES), n_pair=4, n_classes=10, **over):\n    cls, kw = VARIANTS[variant]\n    kw = {**kw, **over}\n    return cls(n_feat=n_feat, n_pair=n_pair, n_particles=n_particles, n_classes=n_classes, **kw)\n\n\ndef from_config(class_name, cfg):\n    return MODEL_CLASSES[class_name](**cfg)\n\n\ndef n_params(model):\n    return sum(p.numel() for p in model.parameters())\n', 'gdsl1/quant.py': '"""Fixed-point quantization-aware training (QAT) that hls4ml can ingest exactly.\n\nEvery quantizer mirrors an ``ap_fixed<W, I, AP_RND_CONV, AP_SAT>`` type:\nvalues are rounded to a grid of 2**-(W-I) and saturated to\n[-2**(I-1), 2**(I-1) - 2**-(W-I)]. Gradients use a clipped straight-through\nestimator.\n\nWeights are quantized with ``torch.nn.utils.parametrize`` so the module stays\nan ``nn.Linear`` (hls4ml\'s FX tracer treats it as a leaf). Before export,\n:func:`bake_weight_quant` removes the parametrization and leaves the weights on\nthe fixed-point grid, so the hls4ml weight type reproduces them bit-exactly.\nActivation quantizers run only while ``model.qat`` is True; at export the same\nrounding is done by the hls4ml ``result`` types (see ``gdsl1.hls``).\n"""\nfrom dataclasses import dataclass\n\nimport torch\nimport torch.nn as nn\nfrom torch.nn.utils import parametrize\n\n\n@dataclass(frozen=True)\nclass FixedPoint:\n    width: int\n    integer: int\n    signed: bool = True\n\n    @property\n    def frac(self):\n        return self.width - self.integer\n\n    @property\n    def lo(self):\n        return -(2.0 ** (self.integer - 1)) if self.signed else 0.0\n\n    @property\n    def hi(self):\n        top = 2.0 ** (self.integer - 1) if self.signed else 2.0 ** self.integer\n        return top - 2.0 ** -self.frac\n\n    def hls(self, rounding="AP_RND_CONV", saturation="AP_SAT"):\n        t = "ap_fixed" if self.signed else "ap_ufixed"\n        return f"{t}<{self.width},{self.integer},{rounding},{saturation}>"\n\n    def quantize(self, x):\n        return fake_quant(x, self)\n\n\nclass _FakeQuant(torch.autograd.Function):\n    @staticmethod\n    def forward(ctx, x, scale, lo, hi):\n        ctx.save_for_backward(x)\n        ctx.lo, ctx.hi = lo, hi\n        # round-half-to-even matches AP_RND_CONV\n        return torch.clamp(torch.round(x * scale) / scale, lo, hi)\n\n    @staticmethod\n    def backward(ctx, g):\n        (x,) = ctx.saved_tensors\n        keep = (x >= ctx.lo) & (x <= ctx.hi)\n        return g * keep, None, None, None\n\n\ndef fake_quant(x, fp: FixedPoint):\n    return _FakeQuant.apply(x, 2.0 ** fp.frac, fp.lo, fp.hi)\n\n\nclass WeightQuant(nn.Module):\n    def __init__(self, fp: FixedPoint):\n        super().__init__()\n        self.fp = fp\n\n    def forward(self, w):\n        return fake_quant(w, self.fp)\n\n\n@dataclass(frozen=True)\nclass QuantSpec:\n    """Precision plan shared by QAT and the hls4ml config."""\n    weight: FixedPoint = FixedPoint(8, 2)\n    bias: FixedPoint = FixedPoint(16, 6)\n    act: FixedPoint = FixedPoint(16, 6)\n\n    def to_dict(self):\n        return {k: [v.width, v.integer] for k, v in\n                (("weight", self.weight), ("bias", self.bias), ("act", self.act))}\n\n    @staticmethod\n    def from_dict(d):\n        return QuantSpec(*(FixedPoint(*d[k]) for k in ("weight", "bias", "act")))\n\n\ndef enable_qat(model: nn.Module, spec: QuantSpec):\n    """Attach weight/bias quantizers to every nn.Linear and turn on the\n    model\'s activation quantizers (``model.qat``/``model.act_fp``)."""\n    for m in model.modules():\n        if isinstance(m, nn.Linear) and not parametrize.is_parametrized(m):\n            parametrize.register_parametrization(m, "weight", WeightQuant(spec.weight))\n            if m.bias is not None:\n                parametrize.register_parametrization(m, "bias", WeightQuant(spec.bias))\n    model.qat = True\n    model.act_fp = spec.act\n    return model\n\n\ndef bake_weight_quant(model: nn.Module):\n    """Remove parametrizations, leaving weights on the fixed-point grid, and\n    disable activation fake-quant (hls4ml result types take over)."""\n    for m in list(model.modules()):\n        if isinstance(m, nn.Linear) and parametrize.is_parametrized(m):\n            for name in list(m.parametrizations.keys()):\n                parametrize.remove_parametrizations(m, name, leave_parametrized=True)\n    model.qat = False\n    return model\n', 'gdsl1/report.py': '"""Convert trained L1 students with hls4ml, emulate bit-accurately, sweep\nreuse factor and build the accuracy / latency / resource table.\n\nUsage:\n  python -m gdsl1.report --students outputs/students --test outputs/test_subset.npz \\\n      --out hls/results [--n_emulate 5000] [--reuse 1,2,4,8]\n  python -m gdsl1.report --synthetic --out hls/results_synthetic   # untrained, no data\n\nWrites  <out>/results.json, <out>/RESULTS.md  and HLS projects  <out>/prj/<variant>_rf<R>/\n(each project contains build_prj.tcl, ready for scripts/synth.sh).\n"""\nimport argparse\nimport glob\nimport json\nimport os\nimport time\n\nimport numpy as np\nimport torch\n\nfrom . import data as D\nfrom . import hls as H\nfrom .models import build, from_config, n_params\nfrom .quant import QuantSpec\n\n# Phase-2 L1T numbers used for the budget check (CMS-TDR-021):\nL1_TOTAL_US = 12.5          # total L1 latency\nBX_NS = 25.0                # 40 MHz bunch crossing\nALGO_BUDGET_NS = 1000.0     # generous per-algorithm budget for a jet tagger in the correlator\nCLOCK_NS = 4.17             # 240 MHz\nDEVICE = {"name": "xcvu13p-flga2577-2-e", "DSP": 12288, "LUT": 1728000, "FF": 3456000,\n          "BRAM_18K": 5376}\n\n\ndef load_students(directory):\n    out = []\n    for p in sorted(glob.glob(os.path.join(directory, "*.pt"))):\n        ck = torch.load(p, map_location="cpu", weights_only=False)\n        m = from_config(ck["class_name"], ck["cfg"])\n        m.load_state_dict(ck["state_dict"])\n        out.append((ck["variant"], m.eval(), ck))\n    return out\n\n\ndef synthetic_students(n):\n    spec = QuantSpec()\n    out = []\n    for v in ("gds_l1_softmax", "gds_l1_linear", "gds_l1_nogate", "deepsets", "mlp"):\n        torch.manual_seed(0)\n        m = build(v, n_particles=n).eval()\n        # put weights on the 8-bit grid like a QAT-baked checkpoint\n        with torch.no_grad():\n            for p in m.parameters():\n                p.copy_(spec.weight.quantize(p) if p.dim() > 1 else spec.bias.quantize(p))\n        out.append((v, m, {"quant": spec.to_dict(), "metrics": {}}))\n    return out\n\n\ndef batches_from_npz(path, n_max, bs=1000):\n    z = np.load(path)\n    n = min(n_max, len(z["y"]))\n    for s in range(0, n, bs):\n        sl = slice(s, min(n, s + bs))\n        b = D.student_inputs(torch.as_tensor(z["x"][sl]).float(), torch.as_tensor(z["v"][sl]),\n                             torch.as_tensor(z["mask"][sl]))\n        b["y"] = torch.as_tensor(z["y"][sl]).long()\n        b["t"] = torch.as_tensor(z["t"][sl]).float() if "t" in z else None\n        yield b\n\n\n@torch.no_grad()\ndef torch_logits(model, b, qat_spec=None):\n    if qat_spec is not None:\n        model.qat, model.act_fp = True, qat_spec.act\n    try:\n        return model(*[b[k] for k in model.inputs]).numpy()\n    finally:\n        model.qat = False\n\n\ndef main(argv=None):\n    ap = argparse.ArgumentParser()\n    ap.add_argument("--students")\n    ap.add_argument("--test")\n    ap.add_argument("--synthetic", action="store_true")\n    ap.add_argument("--n_particles", type=int, default=16)\n    ap.add_argument("--n_emulate", type=int, default=5000)\n    ap.add_argument("--reuse", default="1,2,4")\n    ap.add_argument("--variants", default=None, help="comma list filter")\n    ap.add_argument("--out", default="hls/results")\n    args = ap.parse_args(argv)\n    os.makedirs(args.out, exist_ok=True)\n\n    students = synthetic_students(args.n_particles) if args.synthetic else load_students(args.students)\n    if args.variants:\n        keep = set(args.variants.split(","))\n        students = [s for s in students if s[0] in keep]\n    if args.synthetic:\n        data = [D.synthetic_batch(200, args.n_particles, seed=7)]\n        for b in data:\n            b["t"] = b.pop("teacher_logits")\n    else:\n        data = list(batches_from_npz(args.test, args.n_emulate))\n\n    teacher_acc = None\n    if data[0].get("t") is not None:\n        teacher_acc = float(np.mean(np.concatenate([(b["t"].argmax(1) == b["y"]).numpy() for b in data])))\n\n    rows = []\n    for variant, model, ck in students:\n        spec = QuantSpec.from_dict(ck["quant"])\n        t0 = time.time()\n        prj = os.path.join(args.out, "prj", f"{variant}_rf1")\n        hm = H.convert(model, prj, args.n_particles, ck["quant"], reuse_factor=1, compile=True)\n        ys, yf, yq, yh, yt = [], [], [], [], []\n        for b in data:\n            ys.append(b["y"].numpy())\n            yf.append(torch_logits(model, b))\n            yq.append(torch_logits(model, b, spec))\n            yh.append(H.predict(hm, b, model.inputs))\n            if b.get("t") is not None:\n                yt.append(b["t"].numpy())\n        y, yf, yq, yh = np.concatenate(ys), np.concatenate(yf), np.concatenate(yq), np.concatenate(yh)\n        acc = lambda lg: float((lg.argmax(1) == y).mean())\n        row = {\n            "variant": variant, "params": n_params(model), "n_jets": int(len(y)),\n            "acc_torch_baked": acc(yf), "acc_torch_qat": acc(yq), "acc_hls": acc(yh),\n            "hls_vs_qat_argmax_agree": float((yh.argmax(1) == yq.argmax(1)).mean()),\n            "hls_vs_qat_max_abs_logit_diff": float(np.abs(yh - yq).max()),\n            "teacher_agree_hls": float((yh.argmax(1) == np.concatenate(yt).argmax(1)).mean()) if yt else None,\n            "trained_metrics": ck.get("metrics", {}), "sweep": [],\n        }\n        for rf in [int(r) for r in args.reuse.split(",")]:\n            if rf == 1:\n                g = hm\n            else:\n                g = H.convert(model, os.path.join(args.out, "prj", f"{variant}_rf{rf}"),\n                              args.n_particles, ck["quant"], reuse_factor=rf, compile=False)\n            e = H.estimate(g, reuse_factor=rf, clock_ns=CLOCK_NS)\n            e.pop("layers")\n            e["fits_budget"] = e["latency_ns"] <= ALGO_BUDGET_NS\n            e["dsp_frac"] = e["dsp"] / DEVICE["DSP"]\n            e["lut_mult_frac"] = e["lut_mult"] / DEVICE["LUT"]\n            e["csynth"] = H.parse_vitis_report(os.path.join(args.out, "prj", f"{variant}_rf{rf}"))\n            row["sweep"].append({"reuse_factor": rf, **e})\n        row["sec"] = time.time() - t0\n        print(json.dumps({k: v for k, v in row.items() if k not in ("sweep", "trained_metrics")}),\n              flush=True)\n        rows.append(row)\n        with open(os.path.join(args.out, "results.json"), "w") as f:\n            json.dump({"teacher_acc_same_jets": teacher_acc, "device": DEVICE,\n                       "clock_ns": CLOCK_NS, "budget_ns": ALGO_BUDGET_NS, "rows": rows}, f, indent=1)\n    write_markdown(rows, teacher_acc, args)\n    return rows\n\n\ndef write_markdown(rows, teacher_acc, args):\n    L = []\n    L.append("# hls4ml results" + (" (SYNTHETIC: untrained weights, random data)" if args.synthetic else ""))\n    L.append("")\n    L.append(f"Device {DEVICE[\'name\']}, clock {CLOCK_NS} ns (240 MHz), io_parallel, Latency strategy. "\n             f"Latency and resources are **analytic estimates** (`gdsl1.hls.estimate`) unless a "\n             f"`csynth` column is filled from a Vitis HLS report. Budget: {ALGO_BUDGET_NS:.0f} ns "\n             f"per algorithm (Phase-2 L1T total {L1_TOTAL_US} us, 40 MHz).")\n    L.append("")\n    if teacher_acc is not None:\n        L.append(f"Teacher (dense GDS-ParT, 128 particles, 17 features) accuracy on the same jets: "\n                 f"**{teacher_acc:.4f}**")\n        L.append("")\n    L.append("| model | params | acc float | acc QAT (torch) | acc hls4ml | hls==QAT argmax | "\n             "agree w/ teacher | RF | latency (cycles / ns) | II | DSP (est.) | LUT-mult (est.) | <= budget |")\n    L.append("|---|---|---|---|---|---|---|---|---|---|---|---|---|")\n    for r in rows:\n        for i, s in enumerate(r["sweep"]):\n            head = (f"| {r[\'variant\']} | {r[\'params\']:,} | {r[\'acc_torch_baked\']:.4f} | "\n                    f"{r[\'acc_torch_qat\']:.4f} | {r[\'acc_hls\']:.4f} | {r[\'hls_vs_qat_argmax_agree\']:.4f} | "\n                    f"{\'\' if r[\'teacher_agree_hls\'] is None else format(r[\'teacher_agree_hls\'], \'.4f\')} |"\n                    if i == 0 else "| | | | | | | |")\n            L.append(f"{head} {s[\'reuse_factor\']} | {s[\'cycles\']} / {s[\'latency_ns\']:.0f} | {s[\'ii\']} | "\n                     f"{s[\'dsp\']:,} ({100 * s[\'dsp_frac\']:.1f}%) | {s[\'lut_mult\']:,} "\n                     f"({100 * s[\'lut_mult_frac\']:.1f}%) | {\'yes\' if s[\'fits_budget\'] else \'no\'} |")\n    L.append("")\n    L.append("`acc float` = QAT-trained weights with activation quantization off; `acc QAT` = PyTorch "\n             "fake-quant model; `acc hls4ml` = bit-accurate C-simulation of the generated firmware.")\n    with open(os.path.join(args.out, "RESULTS.md"), "w") as f:\n        f.write("\\n".join(L) + "\\n")\n\n\nif __name__ == "__main__":\n    main()\n', 'gdsl1/train.py': '"""Knowledge distillation + fixed-point QAT of L1 students from the GDS-ParT teacher.\n\nPipeline (runs on a Kaggle GPU kernel, or locally with --synthetic):\n  1. build ragged JetClass caches from ROOT files (vendored gds_part code)\n  2. one pass of the dense teacher over every jet -> teacher logits, and\n     extraction of the student view (top-N candidates, 10 L1-like features)\n     into compact in-memory arrays\n  3. for each student variant: float KD training, then QAT fine-tuning with\n     ap_fixed fake-quant, evaluation, checkpoint export (weights baked onto\n     the fixed-point grid, ready for hls/convert.py)\n\nLoss: alpha * CE(y) + (1 - alpha) * T^2 * KL(softmax(t/T) || softmax(s/T)).\n"""\nimport argparse\nimport glob\nimport json\nimport math\nimport os\nimport sys\nimport time\n\nimport numpy as np\nimport torch\nimport torch.nn.functional as F\n\nfrom . import data as D\nfrom .models import STUDENT_FEATURES, build, n_params\nfrom .quant import FixedPoint, QuantSpec, bake_weight_quant, enable_qat\n\nHERE = os.path.dirname(os.path.abspath(__file__))\n\n\ndef say(*a):\n    print(time.strftime("%H:%M:%S"), *a, flush=True)\n\n\ndef kd_loss(logits, y, t_logits, alpha=0.3, T=4.0):\n    ce = F.cross_entropy(logits, y)\n    if t_logits is None or alpha >= 1.0:\n        return ce\n    kl = F.kl_div(F.log_softmax(logits / T, -1), F.log_softmax(t_logits / T, -1),\n                  log_target=True, reduction="batchmean")\n    return alpha * ce + (1 - alpha) * T * T * kl\n\n\ndef call(model, b):\n    return model(*[b[k] for k in model.inputs])\n\n\n# ---------------------------------------------------------------------------\n# Data: cache -> teacher logits + student arrays\n# ---------------------------------------------------------------------------\ndef load_teacher(path, device):\n    sys.path.insert(0, os.path.join(HERE, "vendor"))\n    from gds_part_colab import GDSParT, GDSParTConfig\n    ck = torch.load(path, map_location="cpu", weights_only=False)\n    model = GDSParT(GDSParTConfig(**ck["config"]))\n    model.load_state_dict(ck["model_state"])\n    return model.to(device).eval()\n\n\n@torch.no_grad()\ndef extract(cache_dir, teacher, n, device, batch_size=256):\n    """Sequential pass over a cache. Returns dict of numpy arrays:\n    x (J,n,10) f16, v (J,n,4) f32, mask (J,n) bool, y (J,), t (J,10) f32."""\n    sys.path.insert(0, os.path.join(HERE, "vendor"))\n    from jetclass_cache import CachedJetLoader, pairwise_features\n    loader = CachedJetLoader(cache_dir, batch_size, shuffle=False)\n    out = {k: [] for k in ("x", "v", "mask", "y", "t")}\n    t0 = time.time()\n    for i, (f, v, m, y) in enumerate(loader):\n        f, v, m = f.to(device), v.to(device), m.to(device)\n        if teacher is not None:\n            with torch.autocast("cuda", dtype=torch.float16, enabled=device == "cuda"):\n                t = teacher(f, pairwise_features(v, m), mask=m).float()\n            out["t"].append(t.cpu().numpy())\n        fs, vs, ms = D.top_n(f[..., STUDENT_FEATURES], v, m, n)\n        out["x"].append(fs.half().cpu().numpy())\n        out["v"].append(vs.cpu().numpy())\n        out["mask"].append(ms.cpu().numpy())\n        out["y"].append(y.numpy())\n        if i % 200 == 0:\n            say(f"  extract {cache_dir}: batch {i}/{len(loader)} ({time.time() - t0:.0f}s)")\n    return {k: np.concatenate(v) for k, v in out.items() if v}\n\n\nclass ArrayLoader:\n    """Mini-batches from in-memory student arrays, already on `device`."""\n\n    def __init__(self, arrs, batch_size, shuffle, device, seed=0):\n        self.a = {k: torch.as_tensor(v).to(device) for k, v in arrs.items()}\n        self.n = len(self.a["y"])\n        self.bs, self.shuffle, self.device = batch_size, shuffle, device\n        self.g = torch.Generator(device="cpu").manual_seed(seed)\n\n    def __len__(self):\n        return math.ceil(self.n / self.bs)\n\n    def __iter__(self):\n        idx = torch.randperm(self.n, generator=self.g) if self.shuffle else torch.arange(self.n)\n        for s in range(0, self.n, self.bs):\n            j = idx[s:s + self.bs].to(self.device)\n            b = D.student_inputs(self.a["x"][j], self.a["v"][j], self.a["mask"][j])\n            b["y"] = self.a["y"][j].long()\n            b["teacher_logits"] = self.a["t"][j].float() if "t" in self.a else None\n            yield b\n\n\nclass SyntheticLoader:\n    def __init__(self, n_batches, batch_size, n, device, seed=0):\n        self.args = (n_batches, batch_size, n, device, seed)\n\n    def __len__(self):\n        return self.args[0]\n\n    def __iter__(self):\n        nb, bs, n, dev, seed = self.args\n        for i in range(nb):\n            yield D.synthetic_batch(bs, n, seed=seed + i, device=dev)\n\n\n# ---------------------------------------------------------------------------\n# Train / eval\n# ---------------------------------------------------------------------------\n@torch.no_grad()\ndef evaluate(model, loader):\n    model.eval()\n    correct = agree = total = 0\n    loss = 0.0\n    for b in loader:\n        logits = call(model, b)\n        loss += F.cross_entropy(logits, b["y"], reduction="sum").item()\n        pred = logits.argmax(-1)\n        correct += (pred == b["y"]).sum().item()\n        if b.get("teacher_logits") is not None:\n            agree += (pred == b["teacher_logits"].argmax(-1)).sum().item()\n        total += len(b["y"])\n    return {"acc": correct / total, "loss": loss / total, "teacher_agreement": agree / total}\n\n\ndef train_phase(model, train, val, epochs, lr, alpha, T, log, tag, max_steps=None):\n    opt = torch.optim.AdamW(model.parameters(), lr=lr, weight_decay=1e-4)\n    total = max(1, epochs * len(train) if max_steps is None else min(max_steps, epochs * len(train)))\n    sched = torch.optim.lr_scheduler.OneCycleLR(opt, max_lr=lr, total_steps=total, pct_start=0.1)\n    step, best, best_state = 0, -1.0, None\n    for ep in range(epochs):\n        model.train()\n        t0, run = time.time(), 0.0\n        for b in train:\n            loss = kd_loss(call(model, b), b["y"], b.get("teacher_logits"), alpha, T)\n            opt.zero_grad(set_to_none=True)\n            loss.backward()\n            torch.nn.utils.clip_grad_norm_(model.parameters(), 1.0)\n            opt.step()\n            sched.step()\n            run += loss.item()\n            step += 1\n            if max_steps is not None and step >= max_steps:\n                break\n        m = evaluate(model, val)\n        m.update(epoch=ep + 1, phase=tag, train_loss=run / max(1, len(train)), sec=time.time() - t0)\n        log.append(m)\n        say(f"  [{tag}] epoch {ep + 1}/{epochs} loss {m[\'train_loss\']:.4f} "\n            f"val acc {m[\'acc\']:.4f} agree {m[\'teacher_agreement\']:.4f}")\n        if m["acc"] > best:\n            best = m["acc"]\n            best_state = {k: v.detach().clone() for k, v in model.state_dict().items()}\n        if max_steps is not None and step >= max_steps:\n            break\n    if best_state is not None:\n        model.load_state_dict(best_state)\n    return model\n\n\ndef run_variant(name, args, train, val, test, device):\n    say(f"=== {name}")\n    torch.manual_seed(args.seed)\n    model = build(name, n_particles=args.n_particles).to(device)\n    log = []\n    say(f"  params: {n_params(model):,}")\n    train_phase(model, train, val, args.epochs, args.lr, args.alpha, args.T, log, "float",\n                args.max_steps)\n    float_val = evaluate(model, val)\n    float_test = evaluate(model, test) if test is not None else None\n\n    spec = QuantSpec(FixedPoint(args.w_bits, args.w_int), FixedPoint(args.b_bits, args.b_int),\n                     FixedPoint(args.a_bits, args.a_int))\n    enable_qat(model, spec)\n    train_phase(model, train, val, args.qat_epochs, args.lr * 0.2, args.alpha, args.T, log,\n                "qat", args.max_steps)\n    qat_val = evaluate(model, val)\n    qat_test = evaluate(model, test) if test is not None else None\n    bake_weight_quant(model)\n\n    ck = {"variant": name, "class_name": type(model).__name__, "cfg": model.cfg,\n          "inputs": list(model.inputs), "state_dict": model.cpu().state_dict(),\n          "quant": spec.to_dict(), "n_params": n_params(model), "history": log,\n          "metrics": {"float_val": float_val, "float_test": float_test,\n                      "qat_val": qat_val, "qat_test": qat_test}}\n    os.makedirs(os.path.join(args.out, "students"), exist_ok=True)\n    torch.save(ck, os.path.join(args.out, "students", f"{name}.pt"))\n    model.to(device)\n    return {k: ck[k] for k in ("variant", "n_params", "metrics")}\n\n\ndef find_root_dir(patterns):\n    for p in patterns:\n        hits = glob.glob(p, recursive=True)\n        if hits:\n            return os.path.dirname(hits[0])\n    return None\n\n\ndef main(argv=None):\n    ap = argparse.ArgumentParser()\n    ap.add_argument("--synthetic", action="store_true")\n    ap.add_argument("--train_dir")\n    ap.add_argument("--val_dir")\n    ap.add_argument("--teacher", help="teacher checkpoint (.pt with model_state + config)")\n    ap.add_argument("--cache_dir", default="./_cache")\n    ap.add_argument("--jets_per_class", type=int, default=100_000)\n    ap.add_argument("--val_jets_per_class", type=int, default=20_000)\n    ap.add_argument("--test_frac", type=float, default=0.5,\n                    help="fraction of the val split held out as test")\n    ap.add_argument("--variants", default="gds_l1_softmax,gds_l1_linear,gds_l1_nogate,deepsets,mlp")\n    ap.add_argument("--n_particles", type=int, default=16)\n    ap.add_argument("--epochs", type=int, default=20)\n    ap.add_argument("--qat_epochs", type=int, default=6)\n    ap.add_argument("--max_steps", type=int, default=None, help="cap per phase (smoke tests)")\n    ap.add_argument("--batch_size", type=int, default=1024)\n    ap.add_argument("--lr", type=float, default=3e-3)\n    ap.add_argument("--alpha", type=float, default=0.3)\n    ap.add_argument("--T", type=float, default=4.0)\n    ap.add_argument("--w_bits", type=int, default=8)\n    ap.add_argument("--w_int", type=int, default=2)\n    ap.add_argument("--b_bits", type=int, default=16)\n    ap.add_argument("--b_int", type=int, default=6)\n    ap.add_argument("--a_bits", type=int, default=16)\n    ap.add_argument("--a_int", type=int, default=6)\n    ap.add_argument("--seed", type=int, default=0)\n    ap.add_argument("--out", default="./outputs")\n    args = ap.parse_args(argv)\n    os.makedirs(args.out, exist_ok=True)\n    device = "cuda" if torch.cuda.is_available() else "cpu"\n    say(f"device {device}  args {vars(args)}")\n\n    if args.synthetic:\n        train = SyntheticLoader(8, 64, args.n_particles, device)\n        val = SyntheticLoader(2, 64, args.n_particles, device, seed=1000)\n        test = SyntheticLoader(2, 64, args.n_particles, device, seed=2000)\n        teacher_ref = None\n    else:\n        sys.path.insert(0, os.path.join(HERE, "vendor"))\n        from jetclass_cache import build_cache\n        teacher = load_teacher(args.teacher, device)\n        arrays = {}\n        for split, d, jpc in (("train", args.train_dir, args.jets_per_class),\n                              ("val", args.val_dir, args.val_jets_per_class)):\n            c = build_cache(d, os.path.join(args.cache_dir, split), 128, jpc)\n            arrays[split] = extract(c, teacher, args.n_particles, device)\n            say(f"{split}: {len(arrays[split][\'y\']):,} jets")\n        del teacher\n        torch.cuda.empty_cache()\n        # split JetClass val into val/test with a fixed permutation\n        nv = len(arrays["val"]["y"])\n        perm = np.random.default_rng(123).permutation(nv)\n        cut = int(nv * (1 - args.test_frac))\n        vsel, tsel = np.sort(perm[:cut]), np.sort(perm[cut:])\n        arrays["test"] = {k: v[tsel] for k, v in arrays["val"].items()}\n        arrays["val"] = {k: v[vsel] for k, v in arrays["val"].items()}\n        teacher_ref = {s: float((arrays[s]["t"].argmax(1) == arrays[s]["y"]).mean())\n                       for s in ("val", "test")}\n        say(f"teacher accuracy (full jet, 128 particles): {teacher_ref}")\n        # compact copy of the test view for bit-accurate hls4ml emulation\n        sub = {k: v[:20000] for k, v in arrays["test"].items()}\n        np.savez_compressed(os.path.join(args.out, "test_subset.npz"), **sub)\n        train = ArrayLoader(arrays["train"], args.batch_size, True, device, args.seed)\n        val = ArrayLoader(arrays["val"], 4096, False, device)\n        test = ArrayLoader(arrays["test"], 4096, False, device)\n\n    results = {"teacher": teacher_ref, "n_particles": args.n_particles, "args": vars(args),\n               "students": []}\n    for name in args.variants.split(","):\n        results["students"].append(run_variant(name.strip(), args, train, val, test, device))\n        with open(os.path.join(args.out, "distill_results.json"), "w") as f:\n            json.dump(results, f, indent=1)\n    say("DONE")\n    return results\n\n\nif __name__ == "__main__":\n    main()\n', 'gdsl1/vendor/fetch_jetclass_subset.py': '"""\nfetch_jetclass_subset.py — download a subset of JetClass ROOT files without\ndownloading the full multi-GB tar archives.\n\nZenodo serves the JetClass tars with HTTP range support, so we read the tar\nheaders remotely to find each member\'s byte offset, then fetch only the\n.root files we want (each file holds 100k jets of a single class).\n\nExample (1 train file/class = 1M jets, 1 val file/class, 1 test file/class):\n    python data/fetch_jetclass_subset.py --out D:/JetClass --train_files 1 --val_files 1 --test_files 1\n"""\nimport argparse\nimport os\nimport re\nimport sys\nimport time\nimport urllib.request\nfrom concurrent.futures import ThreadPoolExecutor\n\nBASE = "https://zenodo.org/records/6619768/files/"\nTARS = {\n    "train": ["JetClass_Pythia_train_100M_part%d.tar" % i for i in range(10)],\n    "val": ["JetClass_Pythia_val_5M.tar"],\n    "test": ["JetClass_Pythia_test_20M.tar"],\n}\nCLASS_PREFIXES = ["ZJetsToNuNu", "HToBB", "HToCC", "HToGG", "HToWW4Q",\n                  "HToWW2Q1L", "ZToQQ", "WToQQ", "TTBar", "TTBarLep"]\nCHUNK = 8 * 1024 * 1024\n\n\ndef _range(url, start, end, timeout=120):\n    req = urllib.request.Request(url, headers={"Range": f"bytes={start}-{end}"})\n    return urllib.request.urlopen(req, timeout=timeout)\n\n\ndef index_tar(url, cache_path):\n    if os.path.exists(cache_path):\n        with open(cache_path) as f:\n            return [(n, int(o), int(s)) for n, o, s in (l.rstrip("\\n").split("\\t") for l in f)]\n    members, off = [], 0\n    while True:\n        h = _range(url, off, off + 511).read()\n        if len(h) < 512 or h[:1] == b"\\0":\n            break\n        name = h[:100].rstrip(b"\\0").decode()\n        prefix = h[345:500].rstrip(b"\\0").decode()\n        size = int(h[124:136].rstrip(b"\\0 ").decode() or "0", 8)\n        members.append((f"{prefix}/{name}" if prefix else name, off + 512, size))\n        off += 512 + ((size + 511) // 512) * 512\n    with open(cache_path, "w") as f:\n        for n, o, s in members:\n            f.write(f"{n}\\t{o}\\t{s}\\n")\n    return members\n\n\ndef download_member(url, offset, size, dest):\n    tmp = dest + ".part"\n    have = os.path.getsize(tmp) if os.path.exists(tmp) else 0\n    if os.path.exists(dest) and os.path.getsize(dest) == size:\n        return dest\n    while have < size:\n        try:\n            with _range(url, offset + have, offset + size - 1) as r, open(tmp, "ab") as f:\n                while True:\n                    buf = r.read(CHUNK)\n                    if not buf:\n                        break\n                    f.write(buf)\n                    have += len(buf)\n        except Exception as e:  # resume on transient network errors\n            print(f"[retry] {os.path.basename(dest)} at {have}/{size}: {e}", flush=True)\n            time.sleep(5)\n        have = os.path.getsize(tmp) if os.path.exists(tmp) else 0\n    os.replace(tmp, dest)\n    print(f"[done] {dest} ({size / 1e6:.0f} MB)", flush=True)\n    return dest\n\n\ndef select(members, prefix, n):\n    pat = re.compile(rf"(^|/){prefix}_\\d+\\.root$")\n    return sorted([m for m in members if pat.search(m[0])])[:n]\n\n\ndef main():\n    ap = argparse.ArgumentParser()\n    ap.add_argument("--out", required=True)\n    ap.add_argument("--train_files", type=int, default=1, help="files per class (100k jets each)")\n    ap.add_argument("--val_files", type=int, default=1)\n    ap.add_argument("--test_files", type=int, default=1)\n    ap.add_argument("--workers", type=int, default=10)\n    args = ap.parse_args()\n\n    jobs = []\n    for split, n in (("train", args.train_files), ("val", args.val_files), ("test", args.test_files)):\n        if n <= 0:\n            continue\n        split_dir = os.path.join(args.out, split)\n        os.makedirs(split_dir, exist_ok=True)\n        needed = {p: n for p in CLASS_PREFIXES}\n        for tar in TARS[split]:\n            if not any(needed.values()):\n                break\n            url = BASE + tar\n            members = index_tar(url, os.path.join(args.out, tar + ".index"))\n            for p in CLASS_PREFIXES:\n                for name, off, size in select(members, p, needed[p]):\n                    jobs.append((url, off, size, os.path.join(split_dir, os.path.basename(name))))\n                    needed[p] -= 1\n\n    print(f"{len(jobs)} files, {sum(j[2] for j in jobs) / 1e9:.1f} GB total", flush=True)\n    with ThreadPoolExecutor(args.workers) as ex:\n        list(ex.map(lambda j: download_member(*j), jobs))\n    print("ALL DOWNLOADS COMPLETE", flush=True)\n\n\nif __name__ == "__main__":\n    sys.exit(main())\n', 'gdsl1/vendor/gds_part_colab.py': '"""\ngds_part_colab.py — Gated Dual-Stream Particle Transformer (GDS-ParT)\n\nA single-file, Colab/Jupyter-friendly PyTorch implementation.\n\nCore idea (contrast with ParT):\n    ParT:     Attention = Softmax( QK^T/sqrt(d) + psi(U) )        [additive logit bias]\n    GDS-ParT: Q\' = Q * gate_Q(U),  K\' = K * gate_K(U)\n              Attention = Softmax( Q\'K\'^T / sqrt(d) )              [multiplicative feature gating]\n\nwhere U is the pairwise interaction tensor (B, N, N, 4) and gate_Q/gate_K are\nlearned, relation-aggregated, per-particle gates.\n\nv2 (default config) extends this with:\n    - identity-initialized gates 1 + tanh(.) in (0, 2) instead of sigmoid (0, 1)\n    - per-layer gates whose neighbour aggregation is attention-weighted by the\n      block\'s current particle state (instead of one uniform mean for all layers)\n    - hybrid fusion: a ParT-style per-head pairwise logit bias alongside the gates\n    - class-attention (CLS token) pooling instead of masked mean pooling\nSee GDSParTConfig for the switches that recover the v1 model.\n\nShapes:\n    particle features:  (B, N, 17)\n    pairwise features:  (B, N, N, 4)\n    padding mask:        (B, N)      True = real particle, False = padded\n    labels:              (B,)        10 jet classes\n\nRun this file directly to execute a synthetic forward/backward sanity check:\n    python gds_part_colab.py\n"""\nimport math\nimport torch\nimport torch.nn as nn\nimport torch.nn.functional as F\nimport torch.utils.checkpoint\n\n\n# ----------------------------------------------------------------------\n# Config\n# ----------------------------------------------------------------------\nclass GDSParTConfig:\n    """v2 options (defaults = full v2 model):\n        gate_mode       "identity": gate = 1 + tanh(.), zero-initialized so every gate\n                        starts at exactly 1 and can amplify (up to 2x) or suppress channels.\n                        "sigmoid": v1 behaviour, gate in (0, 1).\n                        "none": no Q/K gating (ablation; with pair_bias this is plain ParT-style attention).\n        per_layer_gate  each block owns a RelationalGate whose neighbour aggregation is\n                        an attention-weighted sum conditioned on the block\'s current\n                        particle state (v1: one uniform-mean gate shared by all blocks).\n        pair_bias       also add a ParT-style per-head pairwise bias to the attention logits\n                        (hybrid: multiplicative Q/K gating + additive logit bias).\n        n_cls_layers    class-attention blocks with a learned CLS token for pooling\n                        (0 = masked mean pooling, as in v1).\n    Setting gate_mode="sigmoid", per_layer_gate=False, pair_bias=False, n_cls_layers=0\n    gives the v1 architecture.\n    """\n\n    def __init__(\n        self,\n        n_particle_features: int = 17,\n        n_pairwise_features: int = 4,\n        n_classes: int = 10,\n        embed_dim: int = 128,\n        n_heads: int = 8,\n        n_layers: int = 8,\n        ffn_dim: int = 512,\n        pairwise_embed_dim: int = 64,\n        dropout: float = 0.1,\n        max_particles: int = 128,\n        gate_mode: str = "identity",\n        per_layer_gate: bool = True,\n        pair_bias: bool = True,\n        n_cls_layers: int = 2,\n    ):\n        assert embed_dim % n_heads == 0, "embed_dim must be divisible by n_heads"\n        assert gate_mode in ("identity", "sigmoid", "none")\n        self.n_particle_features = n_particle_features\n        self.n_pairwise_features = n_pairwise_features\n        self.n_classes = n_classes\n        self.embed_dim = embed_dim\n        self.n_heads = n_heads\n        self.n_layers = n_layers\n        self.ffn_dim = ffn_dim\n        self.pairwise_embed_dim = pairwise_embed_dim\n        self.dropout = dropout\n        self.max_particles = max_particles\n        self.gate_mode = gate_mode\n        self.per_layer_gate = bool(per_layer_gate)\n        self.pair_bias = bool(pair_bias)\n        self.n_cls_layers = n_cls_layers\n\n\n# ----------------------------------------------------------------------\n# 1. Particle embedding\n# ----------------------------------------------------------------------\nclass ParticleEmbedding(nn.Module):\n    """Projects (B, N, 17) raw single-particle features into (B, N, embed_dim)."""\n\n    def __init__(self, in_features: int, embed_dim: int, dropout: float = 0.1):\n        super().__init__()\n        self.net = nn.Sequential(\n            nn.LayerNorm(in_features),\n            nn.Linear(in_features, embed_dim),\n            nn.GELU(),\n            nn.Linear(embed_dim, embed_dim),\n            nn.Dropout(dropout),\n        )\n\n    def forward(self, x):\n        return self.net(x)\n\n\n# ----------------------------------------------------------------------\n# 2. Pairwise embedding\n# ----------------------------------------------------------------------\nclass PairwiseEmbedding(nn.Module):\n    """Projects (B, N, N, 4) pairwise physics features into a relational\n    tensor of shape (B, N, N, pairwise_embed_dim)."""\n\n    def __init__(self, in_features: int, out_dim: int):\n        super().__init__()\n        self.net = nn.Sequential(\n            nn.Linear(in_features, out_dim),\n            nn.GELU(),\n            nn.Linear(out_dim, out_dim),\n        )\n\n    def forward(self, u):\n        return self.net(u)\n\n\n# ----------------------------------------------------------------------\n# 3. Relational gate\n# ----------------------------------------------------------------------\nclass RelationalGate(nn.Module):\n    """Aggregates the (B, N, N, D) relational tensor over neighbours j into a\n    per-particle summary and maps it to two gates (query and key).\n\n    Aggregation:\n        x is None -> masked uniform mean over neighbours (v1)\n        x given   -> attention-weighted: alpha_ij = softmax_j(<rel_ij, W x_i> / sqrt(D)),\n                     so each particle decides which relations matter given its\n                     current representation.\n    Gates:\n        "identity" -> 1 + tanh(MLP(summary)), last layer zero-init (gate == 1 at init)\n        "sigmoid"  -> sigmoid(MLP(summary))\n    """\n\n    def __init__(self, pairwise_dim: int, embed_dim: int, mode: str = "identity",\n                 conditioned: bool = False):\n        super().__init__()\n        self.mode = mode\n        self.scale = pairwise_dim ** -0.5\n        self.ctx = nn.Linear(embed_dim, pairwise_dim) if conditioned else None\n        self.query_gate = self._mlp(pairwise_dim, embed_dim)\n        self.key_gate = self._mlp(pairwise_dim, embed_dim)\n\n    def _mlp(self, d_in, d_out):\n        last = nn.Linear(d_out, d_out)\n        if self.mode == "identity":\n            nn.init.zeros_(last.weight)\n            nn.init.zeros_(last.bias)\n        return nn.Sequential(nn.Linear(d_in, d_out), nn.GELU(), last)\n\n    def _act(self, z):\n        return 1.0 + torch.tanh(z) if self.mode == "identity" else torch.sigmoid(z)\n\n    def forward(self, rel, key_padding_mask=None, x=None):\n        """\n        rel: (B, N, N, D), rel[b, i, j] = relation of particle i to neighbour j\n        key_padding_mask: (B, N) bool, True = real particle\n        x: (B, N, embed_dim) current particle state (only if conditioned)\n        Returns gate_q, gate_k: (B, N, embed_dim)\n        """\n        if self.ctx is not None and x is not None:\n            c = self.ctx(x).to(rel.dtype)                                  # (B, N, D)\n            score = torch.einsum("bijd,bid->bij", rel, c).float() * self.scale\n            if key_padding_mask is not None:\n                score = score.masked_fill(~key_padding_mask[:, None, :], float("-inf"))\n            alpha = torch.softmax(score, dim=-1).to(rel.dtype)             # (B, N, N)\n            summary = torch.einsum("bij,bijd->bid", alpha, rel)            # (B, N, D)\n        elif key_padding_mask is not None:\n            m = key_padding_mask[:, None, :, None].to(rel.dtype)           # (B, 1, N, 1)\n            denom = m.sum(dim=2).clamp(min=1.0)\n            summary = (rel * m).sum(dim=2) / denom\n        else:\n            summary = rel.mean(dim=2)\n\n        return self._act(self.query_gate(summary)), self._act(self.key_gate(summary))\n\n\n# ----------------------------------------------------------------------\n# 4. Gated dual-stream attention\n# ----------------------------------------------------------------------\nclass GatedDualStreamAttention(nn.Module):\n    """Multi-head self-attention where Q and K are element-wise gated by\n    relation-derived gates *before* the dot product. V is left ungated.\n    An optional additive per-head bias (B, H, N, N) can be added to the logits."""\n\n    def __init__(self, embed_dim: int, n_heads: int, dropout: float = 0.1):\n        super().__init__()\n        self.embed_dim = embed_dim\n        self.n_heads = n_heads\n        self.head_dim = embed_dim // n_heads\n\n        self.q_proj = nn.Linear(embed_dim, embed_dim)\n        self.k_proj = nn.Linear(embed_dim, embed_dim)\n        self.v_proj = nn.Linear(embed_dim, embed_dim)\n        self.out_proj = nn.Linear(embed_dim, embed_dim)\n        self.dropout = nn.Dropout(dropout)\n\n    def _split_heads(self, x):\n        B, N, D = x.shape\n        return x.view(B, N, self.n_heads, self.head_dim).transpose(1, 2)  # (B,H,N,hd)\n\n    def forward(self, x, gate_q, gate_k, attn_mask=None):\n        """\n        x: (B, N, embed_dim); gate_q, gate_k: (B, N, embed_dim)\n        attn_mask: bool (B,1,1,N) True=keep, or float additive bias (B,H,N,N)\n        """\n        B, N, D = x.shape\n        q, k = self.q_proj(x), self.k_proj(x)\n        if gate_q is not None:\n            q, k = q * gate_q, k * gate_k\n        q, k = self._split_heads(q), self._split_heads(k)\n        v = self._split_heads(self.v_proj(x))\n        if attn_mask is not None and attn_mask.is_floating_point():\n            attn_mask = attn_mask.to(q.dtype)\n        out = F.scaled_dot_product_attention(\n            q, k, v, attn_mask=attn_mask,\n            dropout_p=self.dropout.p if self.training else 0.0)\n        out = out.transpose(1, 2).contiguous().view(B, N, D)\n        return self.out_proj(out)\n\n\ndef _ffn(cfg):\n    return nn.Sequential(\n        nn.Linear(cfg.embed_dim, cfg.ffn_dim),\n        nn.GELU(),\n        nn.Dropout(cfg.dropout),\n        nn.Linear(cfg.ffn_dim, cfg.embed_dim),\n        nn.Dropout(cfg.dropout),\n    )\n\n\n# ----------------------------------------------------------------------\n# Transformer block: (optionally per-layer) gate + gated attention + FFN, pre-LN\n# ----------------------------------------------------------------------\nclass GDSParTBlock(nn.Module):\n    def __init__(self, cfg: GDSParTConfig):\n        super().__init__()\n        self.norm1 = nn.LayerNorm(cfg.embed_dim)\n        self.attn = GatedDualStreamAttention(cfg.embed_dim, cfg.n_heads, cfg.dropout)\n        self.norm2 = nn.LayerNorm(cfg.embed_dim)\n        self.ffn = _ffn(cfg)\n        self.gate = (RelationalGate(cfg.pairwise_embed_dim, cfg.embed_dim, cfg.gate_mode,\n                                    conditioned=True)\n                     if cfg.per_layer_gate and cfg.gate_mode != "none" else None)\n\n    def forward(self, x, rel, gates, attn_mask, key_padding_mask):\n        h = self.norm1(x)\n        if self.gate is not None:\n            gate_q, gate_k = self.gate(rel, key_padding_mask, x=h)\n        else:\n            gate_q, gate_k = gates if gates is not None else (None, None)\n        x = x + self.attn(h, gate_q, gate_k, attn_mask)\n        x = x + self.ffn(self.norm2(x))\n        return x\n\n\n# ----------------------------------------------------------------------\n# Class-attention block (CaiT / ParT style): only the CLS token is updated\n# ----------------------------------------------------------------------\nclass ClassAttentionBlock(nn.Module):\n    def __init__(self, cfg: GDSParTConfig):\n        super().__init__()\n        self.norm1 = nn.LayerNorm(cfg.embed_dim)\n        self.attn = nn.MultiheadAttention(cfg.embed_dim, cfg.n_heads, dropout=cfg.dropout,\n                                          batch_first=True)\n        self.norm2 = nn.LayerNorm(cfg.embed_dim)\n        self.ffn = _ffn(cfg)\n\n    def forward(self, x, cls, key_padding_mask=None):\n        """x: (B, N, D) particle tokens, cls: (B, 1, D). Returns updated cls."""\n        kv = self.norm1(torch.cat([cls, x], dim=1))\n        pad = None\n        if key_padding_mask is not None:\n            keep = torch.cat([key_padding_mask.new_ones(x.shape[0], 1), key_padding_mask], dim=1)\n            pad = ~keep  # nn.MultiheadAttention: True = ignore\n        out, _ = self.attn(kv[:, :1], kv, kv, key_padding_mask=pad, need_weights=False)\n        cls = cls + out\n        cls = cls + self.ffn(self.norm2(cls))\n        return cls\n\n\n# ----------------------------------------------------------------------\n# Full model\n# ----------------------------------------------------------------------\nclass GDSParT(nn.Module):\n    def __init__(self, cfg: GDSParTConfig):\n        super().__init__()\n        self.cfg = cfg\n        self.particle_embed = ParticleEmbedding(cfg.n_particle_features, cfg.embed_dim,\n                                                cfg.dropout)\n        self.pairwise_embed = PairwiseEmbedding(cfg.n_pairwise_features,\n                                                cfg.pairwise_embed_dim)\n        # shared (non-conditioned) gate, used only when per_layer_gate=False\n        self.rel_gate = (None if cfg.per_layer_gate or cfg.gate_mode == "none" else\n                         RelationalGate(cfg.pairwise_embed_dim, cfg.embed_dim, cfg.gate_mode))\n        # per-head additive pairwise bias, shared by all blocks (as in ParT)\n        self.pair_bias = (nn.Linear(cfg.pairwise_embed_dim, cfg.n_heads)\n                          if cfg.pair_bias else None)\n\n        self.blocks = nn.ModuleList([GDSParTBlock(cfg) for _ in range(cfg.n_layers)])\n\n        if cfg.n_cls_layers > 0:\n            self.cls_token = nn.Parameter(torch.zeros(1, 1, cfg.embed_dim))\n            nn.init.trunc_normal_(self.cls_token, std=0.02)\n            self.cls_blocks = nn.ModuleList(\n                [ClassAttentionBlock(cfg) for _ in range(cfg.n_cls_layers)])\n        self.final_norm = nn.LayerNorm(cfg.embed_dim)\n\n        self.classifier = nn.Sequential(\n            nn.Linear(cfg.embed_dim, cfg.embed_dim),\n            nn.GELU(),\n            nn.Dropout(cfg.dropout),\n            nn.Linear(cfg.embed_dim, cfg.n_classes),\n        )\n\n    def _pair_inputs(self, pairwise_features, mask):\n        """Relational tensor + attention mask (bool, or additive float bias)."""\n        rel = self.pairwise_embed(pairwise_features)                  # (B, N, N, Dp)\n        attn_mask = None\n        if self.pair_bias is not None:\n            attn_mask = self.pair_bias(rel).permute(0, 3, 1, 2)       # (B, H, N, N)\n            if mask is not None:\n                attn_mask = attn_mask.masked_fill(~mask[:, None, None, :], float("-inf"))\n        elif mask is not None:\n            attn_mask = mask[:, None, None, :]                        # (B, 1, 1, N)\n        gates = None if self.rel_gate is None else self.rel_gate(rel, key_padding_mask=mask)\n        return rel, attn_mask, gates\n\n    def forward(self, particle_features, pairwise_features, mask=None):\n        """\n        particle_features: (B, N, 17)\n        pairwise_features: (B, N, N, 4)\n        mask: (B, N) bool, True = real particle (optional but recommended)\n        Returns: logits (B, n_classes)\n        """\n        x = self.particle_embed(particle_features)\n        rel, attn_mask, gates = self._pair_inputs(pairwise_features, mask)\n\n        # the (B, N, N, D) tensors dominate activation memory: during training\n        # each block is recomputed in backward instead of storing its internals\n        ckpt = self.training and torch.is_grad_enabled()\n        for block in self.blocks:\n            if ckpt:\n                x = torch.utils.checkpoint.checkpoint(\n                    block, x, rel, gates, attn_mask, mask, use_reentrant=False)\n            else:\n                x = block(x, rel, gates, attn_mask, mask)\n\n        if self.cfg.n_cls_layers > 0:\n            cls = self.cls_token.expand(x.shape[0], -1, -1)\n            for blk in self.cls_blocks:\n                cls = blk(x, cls, key_padding_mask=mask)\n            pooled = self.final_norm(cls.squeeze(1))\n        else:\n            x = self.final_norm(x)\n            if mask is not None:\n                m = mask.unsqueeze(-1).to(x.dtype)\n                pooled = (x * m).sum(dim=1) / m.sum(dim=1).clamp(min=1.0)\n            else:\n                pooled = x.mean(dim=1)\n\n        return self.classifier(pooled)\n\n\n# ----------------------------------------------------------------------\n# Synthetic data for sanity-checking the architecture\n# ----------------------------------------------------------------------\ndef make_synthetic_batch(batch_size=16, max_particles=64, cfg: GDSParTConfig = None,\n                          device="cpu"):\n    cfg = cfg or GDSParTConfig()\n    # random, variable particle multiplicity per jet (padded to max_particles)\n    n_real = torch.randint(low=8, high=max_particles + 1, size=(batch_size,))\n    mask = torch.zeros(batch_size, max_particles, dtype=torch.bool)\n    for i, n in enumerate(n_real):\n        mask[i, :n] = True\n\n    particle_features = torch.randn(batch_size, max_particles, cfg.n_particle_features)\n    particle_features = particle_features * mask.unsqueeze(-1)\n\n    pairwise_features = torch.randn(\n        batch_size, max_particles, max_particles, cfg.n_pairwise_features\n    )\n    pair_mask = mask.unsqueeze(1) & mask.unsqueeze(2)\n    pairwise_features = pairwise_features * pair_mask.unsqueeze(-1)\n\n    labels = torch.randint(low=0, high=cfg.n_classes, size=(batch_size,))\n\n    return (\n        particle_features.to(device),\n        pairwise_features.to(device),\n        mask.to(device),\n        labels.to(device),\n    )\n\n\ndef sanity_check(device="cpu"):\n    """One forward pass, one loss computation, one backward pass, one\n    optimizer step — confirms the architecture is differentiable and free\n    of shape mismatches."""\n    torch.manual_seed(0)\n    cfg = GDSParTConfig(embed_dim=64, n_heads=4, n_layers=3, ffn_dim=128,\n                         pairwise_embed_dim=32, max_particles=64)\n    model = GDSParT(cfg).to(device)\n    optimizer = torch.optim.AdamW(model.parameters(), lr=1e-3)\n\n    particle_features, pairwise_features, mask, labels = make_synthetic_batch(\n        batch_size=8, max_particles=cfg.max_particles, cfg=cfg, device=device\n    )\n\n    print(f"particle_features: {tuple(particle_features.shape)}")\n    print(f"pairwise_features: {tuple(pairwise_features.shape)}")\n    print(f"mask:               {tuple(mask.shape)}")\n    print(f"labels:             {tuple(labels.shape)}")\n\n    logits = model(particle_features, pairwise_features, mask=mask)\n    print(f"logits:             {tuple(logits.shape)}  (expect (8, {cfg.n_classes}))")\n\n    loss = F.cross_entropy(logits, labels)\n    print(f"initial loss:       {loss.item():.4f}")\n\n    optimizer.zero_grad()\n    loss.backward()\n\n    total_grad_norm = 0.0\n    n_params_with_grad = 0\n    for p in model.parameters():\n        if p.grad is not None:\n            total_grad_norm += p.grad.norm().item() ** 2\n            n_params_with_grad += 1\n    total_grad_norm = total_grad_norm ** 0.5\n    print(f"grad norm:          {total_grad_norm:.4f} over {n_params_with_grad} tensors")\n\n    optimizer.step()\n    print("optimizer step:     OK")\n\n    n_params = sum(p.numel() for p in model.parameters())\n    print(f"total parameters:   {n_params:,}")\n\n    print("\\nSANITY CHECK PASSED: forward -> loss -> backward -> step, no shape errors.")\n    return model\n\n\nif __name__ == "__main__":\n    device = "cuda" if torch.cuda.is_available() else "cpu"\n    print(f"device: {device}\\n")\n    sanity_check(device=device)\n', 'gdsl1/vendor/jetclass_cache.py': '"""\njetclass_cache.py — memory-efficient JetClass pipeline for GDS-ParT.\n\nWhy: storing the dense (N, N, 4) pairwise tensor per jet costs ~256 KB/jet\nat N=128 (~256 GB for 1M jets). Instead we cache only per-particle arrays\non disk (numpy memmaps) and compute the 4 pairwise features on the GPU per\nbatch from the particle 4-vectors, exactly like the official ParT does.\n\nCache layout (one directory per split, ragged = no padding stored):\n    feats.bin    float16 (P, 17)  normalized particle features, all jets concatenated\n    vectors.bin  float32 (P, 4)   (px, py, pz, E)\n    offsets.npy  int64   (J+1,)   jet j owns particles offsets[j]:offsets[j+1]\n    labels.npy   int64   (J,)\n~1.8 KB/jet on disk (vs ~6.4 KB padded to 128).\n\nParticle features (17), normalized as in the official JetClass_full.yaml\n(x - shift) * scale, clipped to [-5, 5]:\n    0 part_pt_log  1 part_e_log  2 part_logptrel  3 part_logerel  4 part_deltaR\n    5 part_deta    6 part_dphi   7 part_charge\n    8-12 isChargedHadron, isNeutralHadron, isPhoton, isElectron, isMuon\n    13 tanh(d0val) 14 d0err (clip 0..1) 15 tanh(dzval) 16 dzerr (clip 0..1)\n"""\nimport glob\nimport json\nimport os\nimport threading\nimport queue\n\nimport numpy as np\n\nCLASS_PREFIXES = {\n    "QCD":  "ZJetsToNuNu",\n    "Hbb":  "HToBB",\n    "Hcc":  "HToCC",\n    "Hgg":  "HToGG",\n    "H4q":  "HToWW4Q",\n    "Hqql": "HToWW2Q1L",\n    "Zqq":  "ZToQQ",\n    "Wqq":  "WToQQ",\n    "Tbqq": "TTBar",\n    "Tbl":  "TTBarLep",\n}\nCLASS_LIST = list(CLASS_PREFIXES.keys())\n\nBRANCHES = ["part_px", "part_py", "part_pz", "part_energy", "part_deta", "part_dphi",\n            "part_charge", "part_isChargedHadron", "part_isNeutralHadron",\n            "part_isPhoton", "part_isElectron", "part_isMuon",\n            "part_d0val", "part_d0err", "part_dzval", "part_dzerr",\n            "jet_pt", "jet_energy"]\n\n\ndef _files_for_class(data_dir, prefix):\n    # "TTBar_*" would also match "TTBarLep_*", so require digits after the prefix\n    files = glob.glob(os.path.join(data_dir, "**", f"{prefix}_*.root"), recursive=True)\n    return sorted(f for f in files if os.path.basename(f)[len(prefix) + 1:-5].isdigit())\n\n\ndef _process_chunk(a, max_particles):\n    """a: awkward record array of BRANCHES for a chunk of jets.\n    Returns flat per-particle arrays (first `max_particles` per jet, which\n    are the highest-pt ones) plus per-jet particle counts."""\n    import awkward as ak\n    counts = ak.to_numpy(ak.num(a["part_energy"][:, :max_particles])).astype(np.int64)\n    F = lambda b: ak.to_numpy(ak.flatten(a[b][:, :max_particles])).astype(np.float32)\n    px, py, pz, e = F("part_px"), F("part_py"), F("part_pz"), F("part_energy")\n    pt = np.hypot(px, py)\n    jet_pt = np.repeat(np.asarray(a["jet_pt"], dtype=np.float32), counts)\n    jet_e = np.repeat(np.asarray(a["jet_energy"], dtype=np.float32), counts)\n    deta, dphi = F("part_deta"), F("part_dphi")\n\n    with np.errstate(divide="ignore", invalid="ignore"):\n        cols = [\n            (np.log(pt) - 1.7) * 0.7,\n            (np.log(e) - 2.0) * 0.7,\n            (np.log(pt / jet_pt) + 4.7) * 0.7,\n            (np.log(e / jet_e) + 4.7) * 0.7,\n            (np.hypot(deta, dphi) - 0.2) * 4.0,\n            deta, dphi, F("part_charge"),\n            F("part_isChargedHadron"), F("part_isNeutralHadron"), F("part_isPhoton"),\n            F("part_isElectron"), F("part_isMuon"),\n            np.tanh(F("part_d0val")), np.clip(F("part_d0err"), 0, 1),\n            np.tanh(F("part_dzval")), np.clip(F("part_dzerr"), 0, 1),\n        ]\n    feats = np.stack(cols, axis=-1)\n    feats = np.nan_to_num(np.clip(feats, -5, 5), nan=0.0, posinf=0.0, neginf=0.0)\n    vectors = np.stack([px, py, pz, e], axis=-1)\n    return feats.astype(np.float16), vectors, counts\n\n\ndef build_cache(data_dir, cache_dir, max_particles=128, jets_per_class=None, chunk=100_000):\n    """Convert JetClass ROOT files in `data_dir` into ragged memmaps in\n    `cache_dir`. Particles beyond `max_particles` (pt-sorted) are dropped.\n    Skips work if a complete cache already exists."""\n    import uproot\n\n    done_flag = os.path.join(cache_dir, "DONE")\n    if os.path.exists(done_flag):\n        return cache_dir\n    os.makedirs(cache_dir, exist_ok=True)\n\n    plan = []  # (label, file, n_entries)\n    for label, prefix in enumerate(CLASS_PREFIXES.values()):\n        remaining = jets_per_class if jets_per_class else float("inf")\n        files = _files_for_class(data_dir, prefix)\n        if not files:\n            print(f"[warn] no files for {CLASS_LIST[label]} ({prefix}) in {data_dir}")\n        for f in files:\n            if remaining <= 0:\n                break\n            with uproot.open(f) as rf:\n                n = min(rf["tree"].num_entries, remaining)\n            plan.append((label, f, int(n)))\n            remaining -= n\n    n_jets = sum(p[2] for p in plan)\n    print(f"[cache] {data_dir} -> {cache_dir}: {n_jets:,} jets from {len(plan)} files", flush=True)\n\n    feats_path = os.path.join(cache_dir, "feats.bin")\n    vec_path = os.path.join(cache_dir, "vectors.bin")\n    counts = np.empty(n_jets, dtype=np.int64)\n    labels = np.empty(n_jets, dtype=np.int64)\n    jpos, ppos = 0, 0\n    with open(feats_path, "wb") as ff, open(vec_path, "wb") as fv:\n        for label, f, n in plan:\n            with uproot.open(f) as rf:\n                for a in rf["tree"].iterate(BRANCHES, entry_stop=n, step_size=chunk, library="ak"):\n                    feats, vectors, c = _process_chunk(a, max_particles)\n                    ff.write(feats.tobytes())\n                    fv.write(vectors.tobytes())\n                    k = len(c)\n                    counts[jpos:jpos + k] = c\n                    labels[jpos:jpos + k] = label\n                    jpos += k\n                    ppos += len(feats)\n            print(f"  [{CLASS_LIST[label]}] {os.path.basename(f)}: {n:,} jets", flush=True)\n    offsets = np.zeros(n_jets + 1, dtype=np.int64)\n    np.cumsum(counts, out=offsets[1:])\n    np.save(os.path.join(cache_dir, "offsets.npy"), offsets)\n    np.save(os.path.join(cache_dir, "labels.npy"), labels)\n    with open(os.path.join(cache_dir, "meta.json"), "w") as f:\n        json.dump({"n_jets": n_jets, "n_particles": int(ppos), "max_particles": max_particles,\n                   "classes": CLASS_LIST}, f)\n    open(done_flag, "w").close()\n    return cache_dir\n\n\nclass CachedJetLoader:\n    """Batch iterator over a ragged memmapped cache. Each batch is padded\n    only to the longest jet in it, which cuts the O(N^2) pairwise cost\n    substantially. A background thread prefetches batches."""\n\n    def __init__(self, cache_dir, batch_size, shuffle, max_jets=None, seed=0, prefetch=6):\n        self.offsets = np.load(os.path.join(cache_dir, "offsets.npy"))\n        self.labels = np.load(os.path.join(cache_dir, "labels.npy"))\n        n_part = int(self.offsets[-1])\n        self.feats = np.memmap(os.path.join(cache_dir, "feats.bin"), dtype=np.float16,\n                               mode="r", shape=(n_part, 17))\n        self.vectors = np.memmap(os.path.join(cache_dir, "vectors.bin"), dtype=np.float32,\n                                 mode="r", shape=(n_part, 4))\n        self.batch_size = batch_size\n        self.shuffle = shuffle\n        self.rng = np.random.default_rng(seed)\n        self.prefetch = prefetch\n        n = len(self.labels)\n        if max_jets and max_jets < n:\n            self.index = np.sort(np.random.default_rng(1234).choice(n, max_jets, replace=False))\n        else:\n            self.index = np.arange(n)\n\n    def __len__(self):\n        return (len(self.index) + self.batch_size - 1) // self.batch_size\n\n    @staticmethod\n    def _pad(feats, vec, off, labels, sel):\n        """Build a padded batch from in-memory ragged arrays. `off` holds the\n        local particle offsets of the jets in the pool; `sel` picks jets."""\n        start = off[sel]\n        cnt = off[sel + 1] - start\n        n = max(int(cnt.max()), 2)\n        ar = np.arange(n)\n        mask = ar[None, :] < cnt[:, None]\n        rows = (start[:, None] + ar[None, :])[mask]\n        f = np.zeros((len(sel), n, 17), dtype=np.float32)\n        v = np.zeros((len(sel), n, 4), dtype=np.float32)\n        f[mask] = feats[rows]\n        v[mask] = vec[rows]\n        return f, v, mask, labels[sel]\n\n    def _read_block(self, j0, j1):\n        """Sequential read of jets [j0, j1) -> (feats, vec, local offsets, labels)."""\n        p0, p1 = self.offsets[j0], self.offsets[j1]\n        return (np.asarray(self.feats[p0:p1]), np.asarray(self.vectors[p0:p1]),\n                self.offsets[j0:j1 + 1] - p0, self.labels[j0:j1])\n\n    def _batches(self):\n        bs = self.batch_size\n        if not self.shuffle:\n            # contiguous index ranges are read sequentially\n            idx = self.index\n            for s in range(0, len(idx), bs):\n                sel = idx[s:s + bs]\n                if sel[-1] - sel[0] == len(sel) - 1:\n                    f, v, off, y = self._read_block(sel[0], sel[-1] + 1)\n                    yield self._pad(f, v, off, y, np.arange(len(sel)))\n                else:\n                    yield self._pad(self.feats, self.vectors, self.offsets, self.labels, sel)\n            return\n\n        # Disk-friendly shuffling for caches larger than RAM: the dataset is\n        # split into contiguous blocks of `block` jets; a pool is built from\n        # `blocks_per_pool` randomly chosen blocks (each one a sequential\n        # read), then jets inside the pool are shuffled. Within a pool, jets\n        # are bucketed by multiplicity so each batch is padded only to a\n        # similar length, which cuts the O(N^2) pairwise cost.\n        block, blocks_per_pool = 256, 256\n        n = len(self.labels)\n        if len(self.index) != n:\n            raise NotImplementedError("max_jets subsampling is only supported for eval loaders")\n        starts = self.rng.permutation(np.arange(0, n, block))\n        for g in range(0, len(starts), blocks_per_pool):\n            parts = [self._read_block(j0, min(j0 + block, n)) for j0 in starts[g:g + blocks_per_pool]]\n            feats = np.concatenate([p[0] for p in parts])\n            vec = np.concatenate([p[1] for p in parts])\n            counts = np.concatenate([np.diff(p[2]) for p in parts])\n            labels = np.concatenate([p[3] for p in parts])\n            off = np.zeros(len(counts) + 1, dtype=np.int64)\n            np.cumsum(counts, out=off[1:])\n            perm = self.rng.permutation(len(counts))\n            perm = perm[np.argsort(counts[perm], kind="stable")]\n            batches = [perm[k:k + bs] for k in range(0, len(perm), bs)]\n            for i in self.rng.permutation(len(batches)):\n                yield self._pad(feats, vec, off, labels, batches[i])\n\n    def __iter__(self):\n        import torch\n        q = queue.Queue(maxsize=self.prefetch)\n        stop = object()\n\n        def worker():\n            for item in self._batches():\n                q.put(item)\n            q.put(stop)\n\n        threading.Thread(target=worker, daemon=True).start()\n        while True:\n            item = q.get()\n            if item is stop:\n                return\n            yield tuple(torch.from_numpy(x) for x in item)\n\n\ndef pairwise_features(vectors, mask, eps=1e-8):\n    """GPU computation of ParT\'s 4 interaction features for every pair.\n    vectors: (B, N, 4) float tensor of (px, py, pz, E); mask: (B, N) bool.\n    Returns (B, N, N, 4): ln(delta), ln(kt), ln(z), ln(m2). Self-pairs and\n    pairs involving padding are set to 0."""\n    import torch\n    v = vectors.float()\n    px, py, pz, e = v.unbind(-1)\n    pt = torch.sqrt(px ** 2 + py ** 2).clamp(min=eps)\n    rap = 0.5 * torch.log(((e + pz).clamp(min=eps)) / ((e - pz).clamp(min=eps)))\n    phi = torch.atan2(py, px)\n\n    drap = rap[:, :, None] - rap[:, None, :]\n    dphi = torch.remainder(phi[:, :, None] - phi[:, None, :] + torch.pi, 2 * torch.pi) - torch.pi\n    delta = torch.sqrt(drap ** 2 + dphi ** 2).clamp(min=eps)\n    pt_min = torch.minimum(pt[:, :, None], pt[:, None, :])\n    kt = (pt_min * delta).clamp(min=eps)\n    z = (pt_min / (pt[:, :, None] + pt[:, None, :])).clamp(min=eps)\n    s = v[:, :, None, :] + v[:, None, :, :]\n    m2 = (s[..., 3] ** 2 - s[..., 0] ** 2 - s[..., 1] ** 2 - s[..., 2] ** 2).clamp(min=eps)\n\n    out = torch.stack([torch.log(delta), torch.log(kt), torch.log(z), torch.log(m2)], dim=-1)\n    n = mask.shape[1]\n    valid = mask[:, :, None] & mask[:, None, :] & ~torch.eye(n, dtype=torch.bool, device=mask.device)\n    return out * valid[..., None]\n'}
